describe('handle', () => {
  let baseConfig: ConnectorConfig
  let rawBody: string
  let shopifySignature: string

  beforeEach(async () => {
    rawBody = JSON.stringify(SOURCE_EXAMPLE)
    const key = await crypto.subtle.importKey('raw', new TextEncoder().encode('test-secret'), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign'])
    const signature = await crypto.subtle.sign('HMAC', key, new TextEncoder().encode(rawBody))
    shopifySignature = btoa(String.fromCharCode(...new Uint8Array(signature)))

    baseConfig = {
      shopifyClientSecret: 'test-secret',
      slackBotToken: 'xoxb-test-token',
      slackChannel: 'C1234567890',
      rawBody,
      shopifySignature,
    }
  })

  it('posts formatted message to Slack on happy path', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      expect(req.method).toBe('POST')
      expect(req.url).toBe('https://slack.com/api/chat.postMessage')
      expect(req.headers.get('authorization')).toBe('Bearer xoxb-test-token')
      expect(req.json).toEqual({
        channel: 'C1234567890',
        text: 'New order: #1001 from customer@example.com for $123.45 USD',
      })
      return jsonResponse(TARGET_ENDPOINTS[0].response)
    })

    const result = await handle(SOURCE_EXAMPLE as unknown as ShopifyOrderPayload, { ...baseConfig, fetch })
    expect(result).toEqual({ slackChannel: 'C1234567890', slackTimestamp: '1234567890.123456' })
    expect(calls).toHaveLength(1)
  })

  it('throws on missing required field', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const badPayload = { ...SOURCE_EXAMPLE, email: undefined }

    await expect(handle(badPayload as unknown as ShopifyOrderPayload, { ...baseConfig, fetch }))
      .rejects.toThrow('Missing required field: email')
  })

  it('throws on invalid HMAC signature', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const badConfig = { ...baseConfig, shopifySignature: 'invalid-signature' }

    await expect(handle(SOURCE_EXAMPLE as unknown as ShopifyOrderPayload, badConfig))
      .rejects.toThrow('Invalid HMAC signature')
  })

  it('throws on non-2xx Slack response', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ error: 'channel_not_found' }, 404))

    await expect(handle(SOURCE_EXAMPLE as unknown as ShopifyOrderPayload, { ...baseConfig, fetch }))
      .rejects.toThrow('Slack API error: 404 Not Found at POST https://slack.com/api/chat.postMessage')
    expect(calls).toHaveLength(1)
  })

  it('throws when Slack returns ok: false', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({ ok: false, error: 'invalid_auth' }, 200))

    await expect(handle(SOURCE_EXAMPLE as unknown as ShopifyOrderPayload, { ...baseConfig, fetch }))
      .rejects.toThrow('Slack API returned ok: false')
  })

  it('uses correct field mapping in Slack message', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      const body = req.json as { text: string }
      expect(body.text).toContain('#1001')
      expect(body.text).toContain('customer@example.com')
      expect(body.text).toContain('123.45')
      expect(body.text).toContain('USD')
      return jsonResponse(TARGET_ENDPOINTS[0].response)
    })

    await handle(SOURCE_EXAMPLE as unknown as ShopifyOrderPayload, { ...baseConfig, fetch })
    expect(calls).toHaveLength(1)
  })

  it('includes Authorization header with bot token', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      expect(req.headers.get('authorization')).toBe('Bearer xoxb-test-token')
      return jsonResponse(TARGET_ENDPOINTS[0].response)
