export interface ConnectorConfig {
  /** Shopify app client secret (env: SHOPIFY_CLIENT_SECRET) */
  shopifyClientSecret: string
  /** Slack bot token with chat:write scope (env: SLACK_BOT_TOKEN) */
  slackBotToken: string
  /** Slack channel ID or name (e.g., C1234567890 or #general) */
  slackChannel: string
  /** Raw request body as received from Shopify (before JSON parsing) */
  rawBody: string
  /** Value of the X-Shopify-Hmac-Sha256 header */
  shopifySignature: string
  /** Injected fetch for testing */
  fetch?: typeof fetch
}

export interface ShopifyOrderPayload {
  id: number
  name: string
  email: string
  total_price: string
  currency: string
}

export interface HandleResult {
  slackChannel: string
  slackTimestamp: string
}

const REQUIRED_FIELDS: (keyof ShopifyOrderPayload)[] = ['id', 'name', 'email', 'total_price', 'currency']

function validatePayload(payload: unknown): asserts payload is ShopifyOrderPayload {
  if (!payload || typeof payload !== 'object') {
    throw new Error('Payload must be a non-null object')
  }
  const obj = payload as Record<string, unknown>
  for (const field of REQUIRED_FIELDS) {
    if (!(field in obj) || obj[field] === undefined || obj[field] === null) {
      throw new Error(`Missing required field: ${field}`)
    }
  }
}

function timingSafeEqual(a: string, b: string): boolean {
  if (a.length !== b.length) return false
  let diff = 0
  for (let i = 0; i < a.length; i++) {
    diff |= a.charCodeAt(i) ^ b.charCodeAt(i)
  }
  return diff === 0
}

async function verifyHmac(config: ConnectorConfig): Promise<void> {
  const key = await crypto.subtle.importKey(
    'raw',
    new TextEncoder().encode(config.shopifyClientSecret),
    { name: 'HMAC', hash: 'SHA-256' },
    false,
    ['sign']
  )
  const signature = await crypto.subtle.sign('HMAC', key, new TextEncoder().encode(config.rawBody))
  const expectedB64 = btoa(String.fromCharCode(...new Uint8Array(signature)))
  if (!timingSafeEqual(expectedB64, config.shopifySignature)) {
    throw new Error('Invalid HMAC signature')
  }
}

function formatSlackText(payload: ShopifyOrderPayload): string {
  return `New order: ${payload.name} from ${payload.email} for $${payload.total_price} ${payload.currency}`
}

export async function handle(payload: unknown, config: ConnectorConfig): Promise<HandleResult> {
  validatePayload(payload)
  const order = payload as ShopifyOrderPayload

  await verifyHmac(config)

  const text = formatSlackText(order)
  const body = JSON.stringify({ channel: config.slackChannel, text })

  const fetchImpl = config.fetch ?? fetch
  const response = await fetchImpl('https://slack.com/api/chat.postMessage', {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${config.slackBotToken}`,
      'Content-Type': 'application/json',
    },
    body,
  })

  if (!response.ok) {
    throw new Error(`Slack API error: ${response.status} ${response.statusText} at POST https://slack.com/api/chat.postMessage`)
  }

  const data = await response.json() as { ok: boolean; channel: string; ts: string }
  if (!data.ok) {
    throw new Error('Slack API returned ok: false')
  }

  return { slackChannel: data.channel, slackTimestamp: data.ts }
}

